import type { MetadataRoute } from "next";

import { getDictionary } from "@/i18n";
import { defaultLocale, htmlLang } from "@/i18n/config";

/**
 * Web app manifest (`/manifest.webmanifest`).
 *
 * Generated by Next.js's metadata file convention rather than committed as a
 * static JSON file, so the name and description stay in sync with the locale
 * dictionary. Declaring `dir`/`lang` matters here: the primary audience reads
 * right-to-left, and an installed shortcut should open correctly oriented.
 */
export default function manifest(): MetadataRoute.Manifest {
  const dict = getDictionary(defaultLocale);

  return {
    name: dict.meta.homeTitle,
    short_name: dict.meta.siteName,
    description: dict.meta.homeDescription,
    start_url: `/${defaultLocale}`,
    scope: "/",
    display: "standalone",
    // Matches `--bg` in the design tokens (OKLCH 17% 0.03 262 ≈ #0b1220).
    background_color: "#0b1220",
    theme_color: "#0b1220",
    lang: htmlLang[defaultLocale],
    dir: "rtl",
    categories: ["portfolio", "developer", "technology"],
    icons: [
      {
        src: "/favicon.ico",
        sizes: "any",
        type: "image/x-icon",
      },
    ],
  };
}
